#!/usr/bin/env node
/**
 * Compile public/_headers into a module the preview Worker can apply.
 *
 *   node scripts/gen-edge-headers.mjs
 *
 * Why this exists. Workers applies the `_headers` file to static assets it
 * serves directly, and stops applying it the moment a Worker script is in
 * front: "Custom headers defined in the _headers file are not applied to
 * responses generated by your Worker code ... if you have configured
 * assets.run_worker_first ... you will likely need to attach any custom headers
 * you wish to apply directly within that Worker script."
 *
 * That is a quiet way to lose the noindex header, which is the launch switch.
 * So the Worker sets the headers itself — but reading them from the same file,
 * generated on every build, rather than from a second copy that drifts.
 * `public/_headers` stays the one place the switch lives, exactly as
 * docs/LAUNCH-CHECKLIST.md says it does.
 *
 * The parser handles what this file actually uses: comments, blank lines, a
 * path pattern at column zero, and indented `Name: Value` lines under it. It
 * refuses a pattern with a `_headers` placeholder (`:name`) rather than
 * matching it wrongly, because the Worker's matcher does not implement them.
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const SOURCE = 'public/_headers';
const DEST = 'worker/edge-headers.generated.js';

export function parseHeaders(text) {
  const rules = [];
  let current = null;
  for (const [i, raw] of text.split('\n').entries()) {
    const line = raw.replace(/\s+$/, '');
    if (!line || line.trimStart().startsWith('#')) continue;
    if (!/^\s/.test(line)) {
      if (/:[A-Za-z_]/.test(line))
        throw new Error(`${SOURCE}:${i + 1}: placeholder patterns are not supported ` +
                        `by the preview Worker's matcher — ${line}`);
      current = [line.trim(), []];
      rules.push(current);
      continue;
    }
    const at = line.indexOf(':');
    if (at < 0) throw new Error(`${SOURCE}:${i + 1}: expected "Name: Value" — ${line.trim()}`);
    if (!current) throw new Error(`${SOURCE}:${i + 1}: header outside any path block`);
    current[1].push([line.slice(0, at).trim(), line.slice(at + 1).trim()]);
  }
  return rules.filter(([, headers]) => headers.length);
}

const rules = parseHeaders(readFileSync(SOURCE, 'utf8'));
mkdirSync(dirname(DEST), { recursive: true });
writeFileSync(DEST,
  `// GENERATED FROM ${SOURCE} — do not edit. Regenerated by \`npm run build\`.\n` +
  `export const EDGE_HEADER_RULES = ${JSON.stringify(rules, null, 2)};\n`);

const count = rules.reduce((n, [, h]) => n + h.length, 0);
console.log(`edge headers: ${count} header(s) across ${rules.length} rule(s) -> ${DEST}`);
if (!rules.some(([, h]) => h.some(([name]) => name.toLowerCase() === 'x-robots-tag')))
  console.log('  note: no X-Robots-Tag rule. If the site has not launched, that is a mistake.');
